mapper.select:
SELECT DISTINCT M.MENU_ID , M.MENU_NAME , M.MENU_TYPE , M.URL , M.PARENT_MENU_ID , M.MENU_PERMISSION_CODE , M.SORT_ORDER , M.DATA_STATUS , M.CREATED_BY , M.CREATED_AT , M.UPDATED_BY , M.UPDATED_AT FROM TB_MENU M WHERE TRUE
AND M.MENU_ID = #{menuId}
AND M.MENU_ID IN
#{menuId}
AND M.PARENT_MENU_ID = #{parentMenuId}
AND M.MENU_NAME LIKE CONCAT('%', #{menuName}, '%')
AND M.MENU_TYPE = #{menuType}
AND M.DATA_STATUS = #{dataStatus}
ORDER BY M.SORT_ORDER

SELECT M.MENU_ID , M.MENU_NAME , M.MENU_TYPE , M.URL , M.PARENT_MENU_ID , M.MENU_PERMISSION_CODE , M.SORT_ORDER , M.DATA_STATUS , M.CREATED_BY , M.CREATED_AT , M.UPDATED_BY , M.UPDATED_AT FROM TB_MENU M WHERE TRUE
AND M.MENU_ID = #{menuId}
AND M.DATA_STATUS = #{dataStatus}

mapper.insert:
INSERT INTO TB_MENU (
    MENU_ID
  , MENU_NAME
  , MENU_TYPE
  , URL
  , PARENT_MENU_ID
  , MENU_PERMISSION_CODE
  , SORT_ORDER
  , DATA_STATUS
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{menuId}
  , #{menuName}
  , #{menuType}
  , #{url}
  , #{parentMenuId}
  , NULLIF(#{menuPermissionCode}, '')
  , #{sortOrder}
  , #{dataStatus}
  , #{author}
  , #{author}
)

mapper.update:
UPDATE TB_MENU
   SET MENU_NAME            = #{menuName}
     , MENU_PERMISSION_CODE = NULLIF(#{menuPermissionCode}, '')
     , DATA_STATUS          = #{dataStatus}
     , UPDATED_BY           = #{author}
     , UPDATED_AT           = NOW()
 WHERE MENU_ID              = #{menuId}
